import{I as e,c as h,d as r,O as t}from"./chunks/framework.N7KwZWfa-ghp20261122.js";const c=JSON.parse('{"title":"少女迴戰 Wiki 資料站導航｜武將圖鑑、陣容與養成攻略","titleTemplate":false,"description":"查少女迴戰日服和繁中服的武將首發日期、技能與立繪，以及日服星靈獲取、星海套養成、PVE 和 PVP 陣容。","frontmatter":{"title":"少女迴戰 Wiki 資料站導航｜武將圖鑑、陣容與養成攻略","titleTemplate":false,"description":"查少女迴戰日服和繁中服的武將首發日期、技能與立繪，以及日服星靈獲取、星海套養成、PVE 和 PVP 陣容。","breadcrumbLabel":"資料站導航","lastmod":"2026-11-20"},"headers":[],"relativePath":"guides/index.md","filePath":"guides/index.md"}'),n={name:"guides/index.md"};function i(l,a,s,o,d,f){return h(),r("div",null,[...a[0]||(a[0]=[t('<article class="page-shell knowledge-page reference-guide"><h1 id="少女迴戰資料站導航" tabindex="-1">少女迴戰資料站導航 <a class="header-anchor" href="#少女迴戰資料站導航" aria-label="Permalink to &quot;少女迴戰資料站導航&quot;">​</a></h1><p>少女迴戰 Wiki（kaisendb.com）收錄日服《少女廻戦》和繁中服《少女迴戰》的武將技能、分服首發日期與高畫質立繪。日服的材料獲取和限時活動可按資源名和活動名查詢。</p><h2 id="新手攻略與選服" tabindex="-1">新手攻略與選服 <a class="header-anchor" href="#新手攻略與選服" aria-label="Permalink to &quot;新手攻略與選服&quot;">​</a></h2><ul><li><a href="/zh-hant/download/">iOS 與安卓下載</a>可找到日服和繁中服的官方商店，<a href="/zh-hant/servers/">新區開服查詢</a>列出各區服的公告入口。</li><li><a href="/zh-hant/beginner/#beginner-route">新手遊玩必看</a>給出開局、推圖和資源安排。<a href="/zh-hant/beginner/#beginner-tasks">五日任務</a>與<a href="/zh-hant/beginner/#beginner-level-unlocks">等級解鎖</a>可核對階段獎勵和各玩法的開放門檻。</li></ul><h2 id="武將圖鑑、立繪與皮膚" tabindex="-1">武將圖鑑、立繪與皮膚 <a class="header-anchor" href="#武將圖鑑、立繪與皮膚" aria-label="Permalink to &quot;武將圖鑑、立繪與皮膚&quot;">​</a></h2><ul><li><a href="/zh-hant/heroes/">武將圖鑑</a>可按名稱和稀有度查技能、招募、寶物及兩服首發日期。<a href="/zh-hant/weapons/">武靈軀</a>與<a href="/zh-hant/transcendents/">超凡者</a>有各自的技能資料。</li><li><a href="/zh-hant/art-library/">立繪圖鑑</a>可按角色名檢視和下載原版立繪，進入<a href="/zh-hant/skins/">皮膚圖鑑</a>可單獨查變裝與獲取方式。</li></ul><h2 id="_11-月-20-日更新" tabindex="-1">11 月 20 日更新 <a class="header-anchor" href="#_11-月-20-日更新" aria-label="Permalink to &quot;11 月 20 日更新&quot;">​</a></h2><p>現在·幽靈再現（UR+）於 11 月 19 日在日服登場，11 月 20 日在繁中服登場。限時活動在日服叫「暗夜之影」，在繁中服叫「午夜魅影」。可查兩服彈珠排期、武將碎片和三件新寶物的獲取方式。<a href="/zh-hant/heroes/603680">武將詳情</a> · <a href="/zh-hant/art-library/?asset=hero-603680">原版立繪</a> · <a href="/zh-hant/events/dark-shadow/">本期活動攻略</a></p><h2 id="日服與繁中服首發日期" tabindex="-1">日服與繁中服首發日期 <a class="header-anchor" href="#日服與繁中服首發日期" aria-label="Permalink to &quot;日服與繁中服首發日期&quot;">​</a></h2><p><a href="/zh-hant/heroes/601174#character-history">文豪美夢·小元（UR+）</a>在日服於 2026 年 11 月 12 日首次開放招募，繁中服於 2026 年 11 月 13 日首次開放招募。兩服參考的招募記錄與客戶端資料列在武將頁的「首次開放時間」。</p><p><a href="/zh-hant/releases/">首次開放時間表</a>可以按區服核對武將、武靈軀和超凡者的登場日期。同一角色的稀有度和形態各有記錄，例如<a href="/zh-hant/heroes/601170">小元（R）</a>和文豪美夢·小元（UR+）。</p><h2 id="陣容推薦與武將強度榜" tabindex="-1">陣容推薦與武將強度榜 <a class="header-anchor" href="#陣容推薦與武將強度榜" aria-label="Permalink to &quot;陣容推薦與武將強度榜&quot;">​</a></h2><ul><li><a href="/zh-hant/teams/">陣容推薦</a>提供 PVE 首排和 PVP 編成的站位與搭配思路。<a href="/zh-hant/teams/loadouts/">武將強度榜</a>可查 SS、S 檔武將的入榜理由與使用條件。</li></ul><h2 id="裝備養成、資源獲取與寶物羈絆" tabindex="-1">裝備養成、資源獲取與寶物羈絆 <a class="header-anchor" href="#裝備養成、資源獲取與寶物羈絆" aria-label="Permalink to &quot;裝備養成、資源獲取與寶物羈絆&quot;">​</a></h2><ul><li>裝備資源充足時優先做星海套，星海材料不足時用湮滅脈衝過渡。<a href="/zh-hant/equipment/#progression">裝備提升路徑</a>可查合成與升階材料，<a href="/zh-hant/power/">提升戰力</a>可查各養成階段的資源分配。</li><li>日服主角達到 80 級，可在金錠商店用 200 金錠購買 1 個星靈，每日限購 100 次。加入 1 級或以上同盟後，可在盟約商店用 600 盟約幣兌換 1 個星靈，每週限購 20 次。可查<a href="/zh-hant/resources/311/#permanent-sources">星靈常駐來源</a>、<a href="/zh-hant/resources/">資源獲取</a>和<a href="/zh-hant/events/#current">本期活動</a>。</li><li><a href="/zh-hant/dragon-soul/builds/">武將龍魂技能搭配</a>可查每個已開放武將形態的隨機與固定天賦、替換建議和 45 級額外槽解鎖條件。</li><li><a href="/zh-hant/bonds/treasures/">寶物羈絆</a>查啟用條件和星級獎勵。<a href="/zh-hant/marriage/">婚嫁與誓約</a>查婚戒、婚紗和夢中春日的開啟條件。</li></ul><section lang="ja"><h2 id="jp-guide">少女廻戦攻略Wiki</h2><p>日本版『少女廻戦』の攻略案内です。武将の性能やガチャの初登場日、編成、装備素材の入手先を掲載しています。各記事は中国語（簡体字・繁体字）で読めます。</p><ul><li><a href="/zh-hant/beginner/">初心者ガイド</a>で序盤の進め方や機能の解放条件を確認できます。</li><li><a href="/zh-hant/heroes/">武将図鑑</a>と<a href="/zh-hant/teams/">編成例</a>で武将のスキルや配置を調べられます。</li><li><a href="/zh-hant/events/#current">開催中のイベント</a>で日本版の開催期間や報酬を確認できます。</li></ul></section><p>想交流陣容、活動和區服進度，可開啟<a href="/zh-hant/community/">玩家社群</a>。</p></article>',1)])])}const p=e(n,[["render",i]]);export{c as __pageData,p as default};
